import { useDispatch, useSelector } from 'react-redux';
import { toggleDark, setSidebarOpen, selectSidebarOpen } from '../../store/slices/uiSlice';
import { selectActiveChat } from '../../store/slices/chatSlice';
import IconButton from '../ui/IconButton';
import { useTheme } from '../../hooks/useTheme';

export default function Header() {
  const dispatch   = useDispatch();
  const { dark, chatHex, borderHex, textHex } = useTheme();
  const sidebarOpen = useSelector(selectSidebarOpen);
  const activeChat  = useSelector(selectActiveChat);

  return (
    <div style={{
      height: 56, padding: '0 16px',
      display: 'flex', alignItems: 'center', gap: 12,
      borderBottom: `1px solid ${borderHex}`,
      background: chatHex, flexShrink: 0,
    }}>
      {!sidebarOpen && (
        <IconButton onClick={() => dispatch(setSidebarOpen(true))} title="Open sidebar">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
        </IconButton>
      )}
      <span style={{ fontFamily: "'Space Grotesk'", fontWeight: 600, fontSize: 15, color: textHex, flex: 1 }}>
        {activeChat?.title ?? 'New chat'}
      </span>
      <IconButton onClick={() => dispatch(toggleDark())} title="Toggle theme">
        {dark
          ? <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>
          : <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>
        }
      </IconButton>
    </div>
  );
}
